import selfies as sf
parts='[C][O].[O][=C][Branch1][C][O][C][C][=C][C][=C][Branch1][C][I][C][=C][Ring1][#Branch1].[C][C][O][C][C][O][Ring1][=Branch1].[Cl]'.split('.')
for p in parts:
    try:
        s=sf.decoder(p)
    except Exception as e:
        s=f'ERROR {e}'
    print(p,'=>',s)
    if not s.startswith('ERROR'):
        from rdkit import Chem
        m=Chem.MolFromSmiles(s)
        print(' canonical:', Chem.MolToSmiles(m) if m else 'invalid')
